import 'dart:convert'; import 'package:http/http.dart' as http; import 'package:sheshield/config/api_config.dart'; import 'package:sheshield/models/safety_report.dart'; import 'package:sheshield/services/auth_service.dart';
class SafetyReportService { Future<Map<String,String>> _headers() async {final t=await AuthService().readToken();return {'Content-Type':'application/json','Authorization':'Bearer $t'};} Future<List<SafetyReport>> list() async {final r=await http.get(ApiConfig.endpoint('/api/safety-reports'),headers:await _headers());if(r.statusCode!=200)throw const AuthException('Unable to load safety reports.');return (jsonDecode(r.body) as List).map((e)=>SafetyReport.fromJson(e as Map<String,dynamic>)).toList();} Future<void> create({required String location,required double latitude,required double longitude,required String category,required String description}) async {final r=await http.post(ApiConfig.endpoint('/api/safety-reports'),headers:await _headers(),body:jsonEncode({'location':location,'latitude':latitude,'longitude':longitude,'category':category,'description':description}));if(r.statusCode!=201){final b=jsonDecode(r.body) as Map<String,dynamic>;throw AuthException(b['message']?.toString()??'Unable to submit report.');}} }
